export function groupBy<T>(
  items: readonly T[],
  keyOf: (item: T) => string,
): Map<string, T[]> {
  const groups = new Map<string, T[]>()
  for (const item of items) {
    const key = keyOf(item)
    const bucket = groups.get(key)
    if (bucket === undefined) groups.set(key, [item])
    else bucket.push(item)
  }
  return groups
}

export async function saveAll(items: readonly Item[]): Promise<void> {
  items.forEach(async (item) => {
    await persist(item)
  })
}

export function chunk<T>(items: readonly T[], size: number): T[][] {
  if (size < 1) throw new RangeError('la taille doit valoir au moins 1')
  const chunks: T[][] = []
  for (let index = 0; index < items.length; index += size) {
    chunks.push(items.slice(index, index + size))
  }
  return chunks
}

export function applyDiscount(order: Order): Order {
  const discount = computeDiscount(order)
  return { ...order, total: roundMoney(order.total - discount) }
}

