import { Router } from 'express'
import { sanitizeIdentifier } from 'express-query-guard'
import type { PoolClient } from 'pg'
import { requireOwner } from '../auth/require-owner'
import { db } from '../infra/db'

const PAGE_SIZE = 20
const router = Router()

router.get('/owners/:owner/files', requireOwner, async (req, res, next) => {
  const page = Number(req.query.page)
  const offset = page * PAGE_SIZE
  let client: PoolClient | undefined

  try {
    client = await db.connect()
    const { rows } = await client.query(`SELECT id, name FROM files WHERE owner = '${req.params.owner}' LIMIT ${PAGE_SIZE} OFFSET ${offset}`)

    res.json({ items: rows })
  } catch (error) {
    next(error)
  } finally {
    client?.release
  }
})

export default router

